style.css:
@-moz-document domain("discord.com") {
:root {
      --base03:  #002b36; --base02:  #073642; --base01:  #586e75; --base00:  #657b83;
      --base0:   #839496; --base1:   #93a1a1; --base2:   #eee8d5; --base3:   #fdf6e3;
      --yellow:  #b58900; --orange:  #cb4b16; --red:     #dc322f; --magenta: #d33682;
      --violet:  #6c71c4; --blue:    #268bd2; --cyan:    #2aa198; --green:   #859900;
    }

    /* Backgrounds */
    .theme-dark, .theme-light, 
    [class^="bg_"], [class^="container_"], [class^="scroller_"], [class^="chat_"] {
        background-color: var(--base3) !important;
    }

    /* Sidebars and Panels */
    [class^="sidebar_"], [class^="members_"], [class^="panels_"], [class^="privateChannels_"] {
        background-color: var(--base2) !important;
    }

    /* Text Colors */
    [class^="text_"], [class^="contents_"], [class^="header_"], [class^="name_"] {
        color: var(--base00) !important;
    }

    /* Strong Text and Usernames */
    strong, [class^="username_"] {
        color: var(--base01) !important;
    }

    /* Links and Interactive Elements */
    a, [class^="anchor_"] {
        color: var(--blue) !important;
    }

    /* Selected Items */
    [class^="selected_"] {
        background-color: var(--base1) !important;
    }

    /* Input Fields */
    [class^="inner_"], [class^="textArea_"] {
        background-color: var(--base2) !important;
        color: var(--base00) !important;
    }
}
